	    Distributor entity = new Distributor();
            entity.setDistributorId( event.getDistributorId() );
            entity.setName( event.getName() );
            entity.setLicenseNumber( event.getLicenseNumber() );
            entity.setRegion( event.getRegion() );
            entity.setDistributorType( event.getDistributorType() );
	    
    	// ------------------------------------------
